import java.util.Scanner;

public class Main {
	private static Scanner c;
	public static void main(String[] args){
		c=new Scanner(System.in);
		int name=c.nextInt();
		int[] aij=new int[name];
		for(int max=0;max<name;max++){
			aij[max]=c.nextInt();
		}
		int scan=trace(aij,name);
		deepRoad(aij,name);
		System.out.println(scan);
	}
	static void deepRoad(int[] aij,int name){
		for(int max=0;max<name-1;max++){
			System.out.print(aij[max]+" ");
		}
		System.out.println(aij[name-1]);
	}
	static int trace(int[] aij, int name){
		int gain;
		int tokens=0;
		for(int max=0;max<name;max++){
			gain=max;
			for(int right=max;right<name;right++){
				if(aij[right]<aij[gain]){
					gain=right;
				}
			}
			if(gain!=max) tokens++;
			int code=aij[max];
			aij[max]=aij[gain];
			aij[gain]=code;
		}
		return tokens;
	}

}

