		Deque<String> dist = new ArrayDeque<String>();
		for ( int toi = 0; toi<r ; toi++ ) {
			String[] stk = (scanner.readLine()).split(" ");
			dist.addLast(stk[0]);
			corrects.addLast(Integer.parseInt(stk[1]));
		}
		int ans1;
		String value;
		try{
				// System.out.println("a");

			while((ans1 = corrects.pollFirst()) > 0){
				value = dist.pollFirst();
				if ( ans1 <= colors) {
					taro_card = taro_card + ans1;
				// System.out.println("b");

					System.out.println(value + " " + taro_card);
				}else{
					taro_card = taro_card + colors;
					ans1 = ans1 - colors;
					corrects.addLast(ans1);
				// System.out.println("c");

					dist.addLast(value);
				}
			}
		}catch (NullPointerException index){
				// System.out.println("d");

		}
	}
}

