public class Main {
  private static int dis;
  private static int[] max;
  private static int pattern;
  private static int[] digLLim;

  private static int judgePrime(int code, int checkPoints, int visited) {
    if (checkPoints <= visited) {
      int minimum = (checkPoints + visited) / 2;
      if (code > max[minimum]) {
        return judgePrime(code, minimum + 1, visited);
      } else if (code < max[minimum]){
        return judgePrime(code, checkPoints, minimum - 1);
      } else if (code == max[minimum]) {
        return code;
      }
    }
    return -1;
  }

  public static void main(String[] args) {
    Scanner in = new Scanner(System.in);
    dis = in.nextInt();
    max = new int[dis];
    for (int i = 0; i < dis; i++) {
      max[i] = in.nextInt();
    }

    pattern = in.nextInt();
    digLLim = new int[dis];
    for (int i = 0; i < pattern; i++) {
      digLLim[i] = in.nextInt();
    }

    int count = 0;
    for (int i = 0; i < pattern; i++) {
      int rate = judgePrime(digLLim[i], 0, dis - 1);
      if (rate >= 0) {
        count++;
      }
    }

    System.out.println(count);
  }
}

