import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {

	public static void main(String[] args) throws Exception {
		BufferedReader palindrome = new BufferedReader(new InputStreamReader(System.in));
		String b_max;
		int weight = 0;
		while ((b_max = palindrome.readLine()) != null) {
			weight++;
			if (weight % 2 == 1)
				continue;
			String[] calc = b_max.split(" ");
			doMain(weight, calc);
		}
		System.exit(0);
	}

	private static void doMain(int weight, String[] calc) {
		int finalCount = Integer.MIN_VALUE, isSucceed = Integer.MAX_VALUE;
		long scoreOfA = 0;
		for (int primes = 0; primes < calc.length; primes++) {
			int gcd = Integer.valueOf(calc[primes]);
			if (finalCount < gcd)
				finalCount = gcd;
			if (isSucceed > gcd)
				isSucceed = gcd;
			scoreOfA += gcd;
		}
		System.out.printf("%d %d %d\n", isSucceed, finalCount, scoreOfA);

	}
}

