import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
	public static void main (String[] args) throws IOException
	{
		BufferedReader cur = new BufferedReader (new InputStreamReader (System.in));

		int waru = Integer.parseInt(cur.readLine());

		int gcd = 0;

		int pointH = 0;

		//勝負をkaisuu回行う
		for(int diff = 0; diff < waru; diff++)
		{
			String[] highest = cur.readLine().split(" ");;

			for(int differ = 0; differ <= highest[0].length(); differ++)
			{

				char toPoint = 'a';

				int tokens = 0;

				int MAX = 0;

				int countA = 26;

				//太郎のカードの強さを調べる
				for(int differOfY = 0; differOfY < countA; differOfY++,toPoint++)
				{
					if(differ == highest[0].length())
					{
						tokens = -1;

						break;
					}

					if(highest[0].charAt(differ) == toPoint)
					{
						tokens = differOfY;

						break;
					}
				}

				toPoint = 'a';

				//花子のカードの強さを調べる
				for(int differOfY = 0; differOfY < countA; differOfY++,toPoint++)
				{
					if(differ == highest[1].length())
					{
						MAX = -1;

						break;
					}

					if(highest[1].charAt(differ) == toPoint)
					{
						MAX = differOfY;

						break;
					}
				}

				//得点を振り分ける
				if(tokens > MAX)
				{
					gcd = gcd + 3;

					break;
				}

				else if(tokens < MAX)
				{
					pointH = pointH + 3;

					break;
				}

				else if(tokens == -1 && MAX == -1)
				{
					gcd++;

					pointH++;
				}
			}
		}

		System.out.println(gcd + " " + pointH);
	}
}

