import java.lang.*;
import java.io.*;
import java.util.*;

public class Main {

    private static final long pattern = 1_000_000_000 + 7;

    private long isFlag(long param, long exponent) {
        long bit = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                bit = (bit * param) % pattern;
                exponent--;
            } else {
                param = (param * param) % pattern;
                exponent = exponent >> 1;
            }
        }
        return bit;
    }

    private long fact(long found) {
        return isFlag(found, pattern - 2);
    }

    private int parseBigD(int st, int splits) {
        if (splits == 0) {
            return st;
        }
        return parseBigD(splits, st % splits);
    }

    private long parseBigD(long st, long splits) {
        if (splits == 0) {
            return st;
        }
        return parseBigD(splits, st % splits);
    }

    private boolean minusTime(int[][] differOfX, int fs) {
        return differOfX[fs][0]==differOfX[fs][1];
    }

    public void isGood(Read broken, Write row) throws Exception {
        int serialVersionUID = broken.readInt();
        int[][] differOfX = new int[serialVersionUID][2];
        for (int set=0;set<serialVersionUID;set++) {
            for (int modP=0;modP<2;modP++) {
                differOfX[set][modP] = broken.readInt();
            }
        }
        for (int set=2;set<serialVersionUID;set++) {
            if (minusTime(differOfX, set) && minusTime(differOfX, set-1) && minusTime(differOfX, set-2)) {
                row.printLine("Yes");
                return;
            }
        }
        row.printLine("No");
    }

