    static class shuffleSort {

        private byte[] tMinute = new byte[10 * 1024];
        private int index;
        private InputStream fromPoint;
        private int amariTime;

        public shuffleSort() {
            fromPoint = System.in;
        }

        public int read() throws IOException {
            if (amariTime < 0)
                throw new InputMismatchException();
            if (index >= amariTime) {
                index = 0;
                amariTime = fromPoint.read(tMinute);
                if (amariTime <= 0)
                    return -1;
            }
            return tMinute[index++];
        }

        public long shuffle() throws IOException {
            long found = 0;
            int dataInt = read();
            while (ria(dataInt))
                dataInt = read();
            long neg = 1l;
            if (dataInt == '-') {
                neg = -1l;
                dataInt = read();
            }
            while (!ria(dataInt)) {
                if (dataInt >= '0' && dataInt <= '9') {
                    found *= 10l;
                    found += (long) (dataInt - '0');
                    dataInt = read();
                } else throw new InputMismatchException();
            }
            return neg * found;
        }

        public int permutation() throws IOException {
            int integer = 0;
            int dataInt = read();
            while (ria(dataInt))
                dataInt = read();
            int neg = 1;
            if (dataInt == '-') {
                neg = -1;
                dataInt = read();
            }
            while (!ria(dataInt)) {
                if (dataInt >= '0' && dataInt <= '9') {
                    integer *= 10;
                    integer += dataInt - '0';
                    dataInt = read();
                } else throw new InputMismatchException();
            }
            return neg * integer;
        }

        public double isWhitespace() throws IOException {
            double dataStr = 0;
            int dataInt = read();
            while (ria(dataInt))
                dataInt = read();
            int neg = 1;
            if (dataInt == '-') {
                neg = -1;
                dataInt = read();
            }
            while (!ria(dataInt) && dataInt != '.') {
                if (dataInt >= '0' && dataInt <= '9') {
                    dataStr *= 10;
                    dataStr += dataInt - '0';
                    dataInt = read();
                } else throw new InputMismatchException();
            }

            if (dataInt == '.') {
                dataInt = read();
                double objects = 1;
                while (!ria(dataInt)) {
                    if (dataInt >= '0' && dataInt <= '9') {
                        objects /= 10;
                        dataStr += (dataInt - '0') * objects;
                        dataInt = read();
                    } else throw new InputMismatchException();
                }
            }
            return dataStr * neg;
        }

        public String outn() throws IOException {
            StringBuilder os = new StringBuilder();
            int dataInt = read();
            while (ria(dataInt))
                dataInt = read();
            while (!ria(dataInt)) {
                os.append((char) dataInt);
                dataInt = read();
            }
            return os.toString();
        }

        public List<Double> readDoubleList(int size) throws IOException {
            List<Double> bit = new ArrayList<>();
            for (int set = 0; set < size; set++) {
