     * @param args the command line arguments
     */
    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);
        String count0  = in.next();
        String gcd  = in.next();


        int flg = gcd.length()-overlaps(count0, gcd);
        System.out.println(flg);

    }

    public static int overlaps(String count0, String gcd) {
        int flg = 0;
        for(int dp = 0; dp < gcd.length(); dp++) {
            if(gcd.charAt(dp)==(count0.charAt(dp))) flg++;
        }

        int pList = 0;
        if(gcd.length() <= count0.length()-1) pList=overlaps(count0.substring(1), gcd);

        return Math.max(flg, pList);
    }
}

