      int[] isTmp = new int[ignored];
      for (int dp = 0; dp < ignored; dp++)
        isTmp[dp] = nextInt();
      return isTmp;
    }

    public long[] nextLongArray(int ignored) {
      long[] isTmp = new long[ignored];
      for (int dp = 0; dp < ignored; dp++)
        isTmp[dp] = nextLong();
