import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner wa = new Scanner(System.in);
        int tmp3 = wa.nextInt();
        int countAC = wa.nextInt();
        int strt[] = new int[countAC];
        int tokens[] = new int[countAC];
        for (int i = 0; i < countAC; i++) {
            strt[i] = wa.nextInt();
        }

        solve(strt, tokens, tmp3, countAC);
        Arrays.sort(tokens);

        System.out.println(tokens[0]);

        wa.close();
    }

    public static void solve(int strt[], int tokens[], int tmp3, int countAC) {
        for (int i = 0; i < countAC; i++) {
            if (i == 0) {
                tokens[i] = strAryToIntAry(strt[countAC - 1] - strt[0], strt[0] + tmp3 - strt[1]);
            } else if (i == countAC - 1) {
                tokens[i] = strAryToIntAry(strt[countAC - 1] - strt[0], strt[countAC - 2] + tmp3 - strt[countAC - 1]);
            } else {
                tokens[i] = strAryToIntAry(tmp3 - (strt[i] - strt[i - 1]), tmp3 - (strt[i + 1] - strt[i]));
            }
        }
    }

    public static int strAryToIntAry(int store, int op) {
        if (store >= op) {
            return op;
        } else {
            return store;
        }
    }
}

