class Scanner
{
    StringTokenizer st;
    BufferedReader r;

    public Scanner(InputStream sum){	r = new BufferedReader(new InputStreamReader(sum));}

    public String next() throws IOException
    {
        while (st == null || !st.hasMoreTokens())
            st = new StringTokenizer(r.readLine());
        return st.nextToken();
    }

    public int nextInt() throws IOException {return Integer.parseInt(next());}

    public long nextLong() throws IOException {return Long.parseLong(next());}

    public String nextStr() throws IOException {return r.readLine();}

    public double nextToken() throws IOException
    {
        String max = next();
        StringBuilder sh = new StringBuilder("0");
        double par = 0, f = 1;
        boolean delim = false, n = false;
        int startTime = 0;
        if(max.charAt(0) == '-')
        {
            n = true;
            startTime++;
        }
        for(int min = startTime; min < max.length(); min++)
            if(max.charAt(min) == '.')
            {
                par = Long.parseLong(sh.toString());
                sh = new StringBuilder("0");
                delim = true;
            }
            else
            {
                sh.append(max.charAt(min));
                if(delim)
                    f *= 10;
            }
        par += Long.parseLong(sh.toString()) / f;
        return par * (n?-1:1);
    }

    public boolean readB() throws IOException {return r.ready();}


}

