import java.util.Arrays;
import java.util.Scanner;

public class Main {
	public static void main(String [] args) {
		Scanner ms = new Scanner(System.in);
		int out = ms.nextInt();
		int[] arr2 = new int[out];
		int map = 2000000000;
		int height = 0;
		for(int distance = 0; distance < out; distance++) {
			arr2[distance] = ms.nextInt();
		}

		Arrays.sort(arr2);
		if(arr2[0] == arr2[arr2.length - 1]) {
			System.out.println(0);
			System.exit(0);
		}

		for(int distance = arr2[0]; distance < arr2[arr2.length - 1]; distance++) {
			height = 0;
			for(int chars : arr2) {
				height += cost(chars, distance);
				if(height > map) {
					break;
				}
			}
			if(height < map) map = height;
		}

		System.out.println(map);
		ms.close();
	}

	public static int cost(int arr2, int length) {
		return (arr2 - length) * (arr2 - length);
	}
}

