 */
public class Main {
    public static void main(String[] args) {
        InputStream bufPointer = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(bufPointer);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, in, out);
        out.close();
    }

    static class Task {
        public void close(int te, Scanner sc, PrintWriter size) {
            int time = sc.nextInt(), tok = sc.nextInt();
            size.println(lapar(time, tok));
        }

        private long lapar(int time, int tok) {
            return 1l * time * tok / lpar(time, tok);
        }

        private long lpar(int time, int tok) {
            return tok == 0 ? time : lpar(tok, time % tok);
        }

    }

    static class Scanner {
        StringTokenizer ansCount;
        BufferedReader curr;

        public Scanner(FileReader red) {
            curr = new BufferedReader(red);
        }

        public Scanner(InputStream ans2) {
            curr = new BufferedReader(new InputStreamReader(ans2));
        }

        public String readStringArray() {
            while (ansCount == null || !ansCount.hasMoreTokens()) {
                try {
                    ansCount = new StringTokenizer(curr.readLine());
                } catch (IOException counter) {
                    throw new RuntimeException(counter);
                }
            }
            return ansCount.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(readStringArray());
        }

    }
}

