public class Main {
	public static void main(String[] args) throws Exception{
		new Main(new Scanner(System.in), System.out, System.err).exec();
	}
	private final Scanner maxFirst;
	private final PrintStream right, carry;
	public Main(final Scanner maxFirst, final PrintStream right, final PrintStream carry) {
		this.sc = maxFirst;
		this.out = right;
		this.err = carry;
	}

	public void exec() throws Exception{
		final int cost = maxFirst.nextInt();
		final int[] count = new int[cost];
		int k = 0;
		for(int costs=0;costs<cost;costs++) {
			count[costs] = maxFirst.nextInt();
			k += count[costs];
		}

		long queue = 0;
		for(int costs=0;costs<cost;costs++) {
			queue += (k - count[costs])*count[costs];
		}
		right.println(queue/2);
	}
}

