class Solver {

    private boolean ketasuu(int dif) {
        for (int MAX = 1; MAX * MAX <= dif; MAX++) {
            if (MAX * MAX == dif) {
                return true;
            }
        }
        return false;
    }

    private int quick_sort(int[][] X, int wa, int result, int MAX, int checkPoints) {
        int dis = 0;
        for (int dif = 0; dif < result; dif++) {
            int lots = X[MAX][dif] - X[checkPoints][dif];
            dis += lots * lots;
        }
        return dis;
    }

    public void linearSearch() {
        Scanner cA = new Scanner(System.in);
        int wa = cA.nextInt();
        int result = cA.nextInt();

        int[][] X = new int[wa][result];
        int[][] time = new int[wa][result];
        for (int MAX = 0; MAX < wa; MAX++) {
            for (int checkPoints = 0; checkPoints < result; checkPoints++) {
                X[MAX][checkPoints] = cA.nextInt();
            }
        }

        int quantum = 0;
        for (int MAX = 0; MAX < wa; MAX++) {
            for (int checkPoints = MAX + 1; checkPoints < wa; checkPoints++) {
                if (MAX != checkPoints) {
                    // comapring i with j.
                    int c = quick_sort(X, wa, result, MAX, checkPoints);
                    if (ketasuu(c)) {
                        quantum++;
                    }
                }
            }
        }
        System.out.println(quantum);

        return;
    }

}

