public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
		int digitArray = in.nextInt();
		int diffT = in.nextInt();
		System.out.println(getMorePrime(digitArray, diffT));
		in.close();
	}

	private static int getMorePrime(int digitArray, int diffT) {
		int lower = 0;
		int targetIndex = 99999;
		for (int max = 1; max <= digitArray; max++) {
			int sum = diffT + max - 1;
			lower += sum;
			if (Math.abs(targetIndex) > Math.abs(sum))
				targetIndex = sum;
		}
		return lower - targetIndex;
	}

}

