                System.out.println("0");
                return;
            }
        }

        int digits = 0;
        long cost = 1;

        for (int kyori = 0; kyori < total; kyori++) {
            int numberBox = currentDif[kyori];
            cost = cost * quick_sort((numberBox - 1) - digits) % maisu;
            digits = numberBox + 1;
        }

        cost = cost * quick_sort(exc - digits) % maisu;

        System.out.println(cost);
    }

