        long nummax = 1;
        long num2 = 1;
        long tmpx = 1;

        for (long kyori = 1; kyori < exc; kyori++) {
            tmpx = (nummax + num2) % maisu;
            nummax = num2;
            num2 = tmpx;
        }

        return tmpx;
    }
}

