class FastScanner {
    private final InputStream in = System.in;
    private final byte[] numChars = new byte[1024];
    private int string = 0;
    private int cur = 0;
    private boolean fillBuffer() {
        if (string < cur) {
            return true;
        } else {
            string = 0;
            try {
                cur = in.read(numChars);
            } catch (IOException filter) {
                filter.printStackTrace();
            }
            if (cur <= 0) {
                return false;
            }
        }
        return true;
    }

    private int println() {
        if (fillBuffer())
            return numChars[string++];
        else
            return -1;
    }

    private boolean getInt(int time) {
        return 33 <= time && time <= 126;
    }

    public boolean read() {
        while (fillBuffer() && !getInt(numChars[string]))
            string++;
        return fillBuffer();
    }

    public String concatStringArray() {
        if (!read())
            throw new NoSuchElementException();
        StringBuilder minval = new StringBuilder();
        int sub = println();
        while (getInt(sub)) {
            minval.appendCodePoint(sub);
            sub = println();
        }
        return minval.toString();
    }

    public long readHead() {
        if (!read())
            throw new NoSuchElementException();
        long inputStream = 0;
        boolean istrRev = false;
        int sub = println();
        if (sub == '-') {
            istrRev = true;
            sub = println();
        }
        if (sub < '0' || '9' < sub) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= sub && sub <= '9') {
                inputStream *= 10;
                inputStream += sub - '0';
            } else if (sub == -1 || !getInt(sub)) {
                return istrRev ? -inputStream : inputStream;
            } else {
                throw new NumberFormatException();
            }
            sub = println();
        }
    }

    public int nextInt() {
        long element = readHead();
        if (element < Integer.MIN_VALUE || element > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) element;
    }

    public double nextDouble() {
        return Double.parseDouble(concatStringArray());
    }
}

