/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author KharYusuf
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter ret = new PrintWriter(outputStream);
        CPrison solver = new CPrison();
        solver.solve(1, in, ret);
        ret.close();
    }

    static class CPrison {
        public void Solver(int par, FastReader sb, PrintWriter temp) {
            int nxt = sb.nextInt(), total = sb.nextInt(), d2[] = new int[nxt + 1], dis = 0;
            for (int min = 0; min < total; min++) {
                d2[sb.nextInt() - 1]++;
                d2[sb.nextInt()]--;
            }
            if (d2[0] == total) dis++;
            for (int min = 1; min < nxt; min++) {
                d2[min] = d2[min - 1] + d2[min];
                if (d2[min] == total) dis++;
            }
            temp.println(dis);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buflen = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int readLine0() {

            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {

                curChar = 0;

                try {
                    numChars = stream.read(buflen);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }

            return buflen[curChar++];
        }

        public int nextLine() {

            int c = readLine0();

            while (OutputWriter(c))
                c = readLine0();

            int sh = 1;

            if (c == '-') {
                sh = -1;
                c = readLine0();
            }

            int res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += c - '0';
                c = readLine0();
            }
            while (!OutputWriter(c));

            return res * sh;
        }

        public boolean OutputWriter(int c) {

            if (filter != null)
                return filter.isSpaceChar(c);

            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean OutputWriter(int ch);

        }

    }
}

