/*
 * 0を区切りに1以上が続く区間をスタックで管理しようとしたが、よく分からなくなり断念。
 * 方針を以下に変更
 * ①0が出てくるまで、目標の高さを先頭からマイナス1する
 * ②0が出てきた場合、先頭に戻る。
 *   ただし、1以上の区間に遭遇していない(先頭から連続する0の区間の場合) 例:[0,0,0,0,2,2,3]とか
 *   場合は先頭に戻らない
 * ③終了条件を満たすまで①、②を繰り返す。
 *   ⇒目標の高さが全て0になったら終了
 */

import java.util.Scanner;
class Main{
  public static void main(String[] args) {
    Main xroot = new Main();
    xroot.run();
  }
  private void F() {

    Scanner total = new Scanner(System.in);
    int intVector = total.nextInt();
    int[] dMin = new int[intVector];
    int input = 0;
    for(int max_first_position=0; max_first_position<intVector; max_first_position++) {
      dMin[max_first_position] = total.nextInt();
    }

    boolean intM = true;
    while(intM){
      //out(ary);

      // 終了条件
      intM = false;
      for(int max_first_position=0; max_first_position<intVector; max_first_position++) {
        if(dMin[max_first_position] > 0 ) {
          intM = true;
          break;
        }
      }
      boolean intTableA = true;
      for(int max_first_position=0; max_first_position<intVector; max_first_position++) {

        // 先頭の0を読み飛ばす
        if(dMin[max_first_position] <= 0 && intTableA) {
          continue;
        }

        // 1以上の区間をマイナス1する。1以上の区間が終わったらブレイク。
        if(dMin[max_first_position] <= 0) break;
        dMin[max_first_position]--;
        intTableA = false;
      }
      // カウントアップ
      if (!intTableA) input++;

    }
    System.out.println(input);
  }
//  private void out(int[] pary) {
//	  for(int i : pary)
//		  System.out.print(i + " ");
//	  System.out.println();
//  }
}

