import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner ans2 = new Scanner(System.in);

        int data = ans2.nextInt();
        int[] isPrime = new int[data];
        for (int distance_sqrt = 0; distance_sqrt < isPrime.length; ++distance_sqrt) {
            isPrime[distance_sqrt] = ans2.nextInt();
        }

        System.out.println(output(isPrime));

        ans2.close();
    }

    static int output(int[] isPrime) {
        int[] m = new int[isPrime.length];
        Arrays.fill(m, Integer.MAX_VALUE);
        m[0] = 0;

        for (int distance_sqrt = 1; distance_sqrt < m.length; ++distance_sqrt) {
            for (int flag = 1; flag <= 2 && flag <= distance_sqrt; ++flag) {
                m[distance_sqrt] = Math.min(m[distance_sqrt], m[distance_sqrt - flag] + Math.abs(isPrime[distance_sqrt] - isPrime[distance_sqrt - flag]));
            }
        }

        return m[m.length - 1];
    }
}

