import java.io.*;
import java.util.*;
class Main {

    static int[] INF;
    static int[] set;
    static int line, m;

    static int operateStack(int cost, int row)
    {
        //base cases
        if(row-cost<=0)
			return 0;
		if(row-cost==1)
		    return Math.abs(INF[row]-INF[cost]);


        if(set[cost]==-1)
        {
            int time = Integer.MAX_VALUE;
            for(int sam = 1; sam<=m; sam++)
            {   
                if(cost + sam<=line - 1)
                    time = Math.min(time, operateStack(cost + sam, row) + Math.abs(INF[cost] - INF[cost + sam]));
            }
            set[cost] = time;
            return time;
        }
        else
            return set[cost];
    }

	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);

		line = sc.nextInt();
		m = sc.nextInt();

		INF = new int[line];
		set = new int[line];

		for(int sam=0; sam<line; sam++)
			INF[sam] = sc.nextInt();

		Arrays.fill(set, -1); 

		System.out.println(operateStack(0, line-1));
	}
}

