    static class removeChild {
        private final BufferedReader in;
        private static int pos;
        private static int tokenizer;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] p_sorted = new boolean[256];
        private static boolean[] permutaion = new boolean[256];
        private static boolean[] strLine = new boolean[256];

        static {
            for (int e_i = 0; e_i < 10; e_i++) {
                p_sorted['0' + e_i] = true;
            }
            p_sorted['-'] = true;
            permutaion[' '] = permutaion['\r'] = permutaion['\n'] = permutaion['\t'] = true;
            strLine['\r'] = strLine['\n'] = true;
        }

        public removeChild(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int readLine() {
            if (pos >= tokenizer) {
                pos = 0;
                try {
                    tokenizer = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (tokenizer <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextLongArray() {
            int children = 0;
            str[children++] = nextDoubleArray();
            children = reads(children, permutaion);
            int e_i = 0;
            int builder = 0;
            if (str[0] == '-') {
                e_i = 1;
            }
            for (; e_i < children; e_i++) builder = builder * 10 + str[e_i] - '0';
            if (str[0] == '-') {
                builder = -builder;
            }
            return builder;
        }

        public char[] nextCharArray() {
            int children = 0;
            children = reads(children, permutaion);
            char[] builder = new char[children + 1];
            for (int e_i=0; e_i < children; e_i++)		builder[e_i] = str[e_i];
            builder[children] = 0x00;
            return builder;
        }

        public char nextDoubleArray() {
            while (true) {
                final int ch = readLine();
                if (!permutaion[ch]) {
                    return (char) ch;
                }
            }
        }

        int reads(int children, boolean[] accept) {
            try {
                while (true) {
                    final int ch = readLine();
                    if (accept[ch]) {
                        break;
                    }
                    if (str.length == children) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[children++] = (char) ch;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return children;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }
    }
}

