public class Main {

    void Solver() throws IOException {
        int N = ni();
        int visited = ni();
        int m= ni()-1;
        int[] ans = new int[N];
        for (int ii = 0; ii < visited; ii++) {
            int target = ni()-1;
            ans[target] = 1;
        }
        int isprime = 0;
        int parent = 0;
        for (int ii = m+1; ii < N; ii++) {
            isprime += ans[ii];
        }
        for (int ii = m-1; ii >=0; ii--) {
            parent += ans[ii];
        }

        tokenizer.println(Math.min(parent, isprime));
    }

    final int time = 1000000007;
    final BigInteger gen = BigInteger.valueOf(time);

    int isFull(int max, int dy){
        int values = (int)((max * 1L * dy) % time);
        return values>=0 ? values : values+time;
    }
    int gcd(int max, int dy) {
        max += dy;
        if(max < 0) max += time;
        if(max>=time) max -= time;
        return max;
    }
    int sub(int max, int dy){
        max = gcd(max,time-dy);
        if(max < 0) max += time;
        if(max>=time) max -= time;
        return max;
    }
    String ns() throws IOException {
        while (!tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine(), " ");
        }
        return tok.nextToken();
    }

    int ni() throws IOException {
        return Integer.parseInt(ns());
    }

    long nl() throws IOException {
        return Long.parseLong(ns());
    }

    double nd() throws IOException {
        return Double.parseDouble(ns());
    }

    String[] nsa(int n) throws IOException {
        String[] par = new String[n];
        for (int ii = 0; ii < n; ii++) {
            par[ii] = ns();
        }
        return par;
    }

    int[] nia(int n) throws IOException {
        int[] par = new int[n];
        for (int ii = 0; ii < n; ii++) {
            par[ii] = ni();
        }
        return par;
    }

    long[] nla(int n) throws IOException {
        long[] par = new long[n];
        for (int ii = 0; ii < n; ii++) {
            par[ii] = nl();
        }
        return par;
    }

    static BufferedReader in;
    static PrintWriter tokenizer;
    static StringTokenizer tok;

    public static void main(String[] args) throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = new PrintWriter(System.out);
        tok = new StringTokenizer("");
        Main main = new Main();
        main.solve();
        tokenizer.close();
    }
}

